// The reading beside the card: its name, upright or reversed, three words
// for it, and the reading, on deep midnight with gold.
import { readRecord, WEEKDAYS, MONTHS } from './record'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const record = readRecord(app.state.reading)
  const text = record && record.text
  const u = Math.min(W, H) / 100
  const pad = Math.round(u * 6)
  const now = new Date()
  const date = `${WEEKDAYS[now.getDay()]} ${now.getDate()} ${MONTHS[now.getMonth()]}`

  const round = roundColumn(app, W, H)
  if (round && !text) {
    // On a round panel, the note poured into the circle's right-hand part.
    const R = round.r
    const lines = flowIntoCircleCentred(
      [
        { text: 'The cards are being shuffled', className: `font-[Cormorant_Garamond] font-bold text-[${Math.round(R * 0.11)}px] leading-[${Math.round(R * 0.13)}px] text-[#e8c872]`, lead: Math.round(R * 0.13), gap: Math.round(R * 0.04) },
        { text: record && record.error ? String(record.error) : 'A card is drawn each morning. Add an OpenAI API key in Settings.', className: 'font-[PT_Sans] text-[15px] leading-[20px] text-[#b9b6d8]', lead: 20, gap: 0 },
      ],
      Math.round(R * 0.2),
      H - Math.round(R * 0.14),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[#141433]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }

  if (!text) {
    return (
      <div className={`flex flex-col w-full h-full bg-[#141433] p-[${pad}px] justify-center`}>
        <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.max(16, Math.round(u * 7))}px] text-[#e8c872]`}>The cards are being shuffled</div>
        <div className={`font-[PT_Sans] text-[${Math.max(12, Math.round(u * 4))}px] text-[#b9b6d8] mt-[${Math.round(u * 2)}px]`}>
          {record && record.error ? record.error : 'A card is drawn each morning. Add an OpenAI API key in Settings.'}
        </div>
      </div>
    )
  }
  if (round) {
    // On a round panel: the reading poured into the circle's right-hand
    // part, its lines running out to the rim.
    const R = round.r
    const size = Math.max(14, Math.round(R * 0.066))
    const lines = flowIntoCircleCentred(
      [
        { text: 'Card of the day', className: 'font-[PT_Sans] uppercase text-[14px] leading-[18px] text-[#8f8cc0]', lead: 18, gap: 4 },
        { text: String(text.card), className: `font-[Cormorant_Garamond] font-bold text-[${Math.round(R * 0.13)}px] leading-[${Math.round(R * 0.14)}px] text-[#f1d98c]`, lead: Math.round(R * 0.14), gap: 4, lines: 2 },
        { text: [text.reversed ? 'Reversed' : '', (text.keywords || []).join(' · ')].filter(Boolean).join(' · '), className: `font-[PT_Sans] text-[${size}px] leading-[${Math.round(size * 1.3)}px] text-[#c9a64a]`, lead: Math.round(size * 1.3), gap: Math.round(R * 0.05), lines: 2 },
        { text: String(text.reading), className: `font-[PT_Sans] text-[${size}px] leading-[${Math.round(size * 1.35)}px] text-[#e4e2f5]`, lead: Math.round(size * 1.35), gap: 0 },
      ],
      Math.round(R * 0.24),
      H - Math.round(R * 0.14),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-gradient-to-b from-[#1b1b45] to-[#0e0e26]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }
  const words = String(text.reading).split(/\s+/).length
  const body = Math.round(Math.max(u * 3, Math.min(u * 4.6, Math.sqrt(((W - pad * 2) * (H - pad * 2 - u * 30)) / (words * 7)))))
  return (
    <div className={`flex flex-col w-full h-full bg-gradient-to-b from-[#1b1b45] to-[#0e0e26] px-[${pad}px] py-[${Math.round(pad * 0.8)}px]`}>
      <div className={`font-[PT_Sans] uppercase text-[${Math.round(u * 2.6)}px] text-[#8f8cc0]`}>{`Card of the day · ${date}`}</div>
      <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 8)}px] leading-none text-[#f1d98c] mt-[${Math.round(u * 1.6)}px]`}>{text.card}</div>
      {text.reversed ? <div className={`font-[PT_Sans] text-[${Math.round(u * 3)}px] text-[#c9a64a] mt-[${Math.round(u * 0.8)}px]`}>Reversed</div> : null}
      <div className={`flex flex-wrap gap-[${Math.round(u * 1.4)}px] mt-[${Math.round(u * 2.4)}px]`}>
        {(text.keywords || []).map((k: string) => (
          <div className={`font-[PT_Sans] text-[${Math.round(u * 2.8)}px] text-[#f1d98c] border border-[#c9a64a] rounded-full px-[${Math.round(u * 2)}px] py-[${Math.round(u * 0.4)}px]`}>{k}</div>
        ))}
      </div>
      <div className={`font-[PT_Sans] text-[${body}px] leading-relaxed text-[#e4e2f5] mt-[${Math.round(u * 3)}px] flex-1 min-h-0 overflow-hidden`}>{text.reading}</div>
      <div className={`font-[PT_Sans] text-[${Math.round(u * 2.2)}px] text-[#6f6c9a]`}>For fun. Painted and read by OpenAI.</div>
    </div>
  )
}

// On a round panel only the circle inside the square shows, and the scene's
// split puts this page in its right-hand column: the panel's full height, up
// to its right edge. Where the circle is in the page's own pixels, or null on
// every other panel and in any other room.
function roundColumn(app: FrameOSApp, W: number, H: number) {
  const side = Math.min(app.frame.width, app.frame.height)
  if (app.frame.round !== true || Math.abs(H - side) > 1 || W >= side - 1) return null
  return { cx: W - side / 2, cy: H / 2, r: side / 2 }
}

type Flowed = { text: string; className: string; y: number; left: number; width: number }

// The same, moved down to the middle of the room when it leaves room below.
function flowIntoCircleCentred(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const first = flowIntoCircle(blocks, top, bottom, at, seam)
  const last = first[first.length - 1]
  const slack = last ? bottom - (last.y + blocks[blocks.length - 1].lead) : 0
  if (slack < 20) return first
  const lower = flowIntoCircle(blocks, top + Math.round(slack / 2), bottom, at, seam)
  const said = (lines: Flowed[]) => lines.map((line) => line.text).join(' ')
  return said(lower) === said(first) ? lower : first
}

// Blocks of text poured into the circle from `top` to `bottom`: each line
// from the page's left edge (`seam` in) to the rim (12 px in), measured so
// nothing is cut. A block stops at its `lines`, the text at `bottom`, and
// what does not fit ends in "…".
function flowIntoCircle(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const out: Flowed[] = []
  let y = top
  const shorten = (line: Flowed | undefined) => {
    if (line) line.text = line.text.includes(' ') ? line.text.replace(/\s+\S+$/, '…') : line.text + '…'
  }
  for (const block of blocks) {
    let used = 0
    const paragraphs = block.text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean)
    for (let p = 0; p < paragraphs.length; p++) {
      const words = paragraphs[p].split(/\s+/)
      let k = 0
      while (k < words.length) {
        if (y + block.lead > bottom || (block.lines && used >= block.lines)) {
          shorten(used ? out[out.length - 1] : undefined)
          if (y + block.lead > bottom) return out
          p = paragraphs.length
          break
        }
        const dy = Math.max(Math.abs(y - at.cy), Math.abs(y + block.lead - at.cy))
        const half = Math.sqrt(Math.max(0, at.r * at.r - dy * dy))
        const left = Math.max(0, at.cx - half) + seam
        const width = Math.floor(at.cx + half - 12 - left)
        if (width < block.lead * 3) {
          y += block.lead
          continue
        }
        const tries = []
        for (let n = 1; n <= Math.min(words.length - k, 24); n++) tries.push(words.slice(k, k + n).join(' '))
        const heights = frameos.measureText(tries, { className: block.className, width })
        let n = 1
        while (n < tries.length && heights[n] <= heights[0]) n++
        out.push({ text: tries[n - 1], className: block.className, y, left: Math.round(left), width })
        k += n
        used++
        y += block.lead
      }
      if (p < paragraphs.length - 1) y += Math.round(block.lead * 0.35)
    }
    y += block.gap
  }
  return out
}

